ROOT=Path(__file__).resolve().parent
OUT=ROOT/'dist'
DOCS=[
('getting-started','Start here','Start with the basics','An introduction to DeskRally, the two connection types, and what you need before a session.'),
('receiving-support','Receiving support','Get help with your computer','What to expect when a technician asks you to join a one-time support session.'),
('technician-guide','Technician guide','Connect and work','A practical guide to the browser console, session controls, and finishing a support session.'),
('self-hosting','Self-hosting','Understand the moving parts','A plain-language map of the console, agents, server, database, and relay.'),
('security','Security & consent','Know who has access','Set boundaries for remote access, protect credentials, and keep support sessions intentional.')]
PAGES={}
def page(path,title,desc,body,kind='standard'):PAGES[path]={'title':title,'description':desc,'body':body,'kind':kind}
def arrow():return '<span aria-hidden="true">↗</span>'
def card(slug,title,desc,tag='Guide'):
 return f'<a class="doc-card" href="/docs/{slug}/"><span class="eyebrow">{tag}</span><h3>{title} {arrow()}</h3><p>{desc}</p></a>'
page('/','Remote support. Keep it simple.','DeskRally is a Windows-first remote support and unattended access project, with a browser console and self-hosted infrastructure.',f'''
<section class="hero wrap">
 <div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> Windows-first · Self-hosted</p>
 <h1>Remote support.<br><span>Keep it simple.</span></h1>
 <p class="hero-lede">Help someone with a Windows computer, or connect to a machine you manage. DeskRally gives you a browser console and a server you run yourself.</p>
 <div class="actions"><a class="button primary" href="/docs/getting-started/">Start with the basics <span aria-hidden="true">→</span></a><a class="text-link" href="/about/">What is DeskRally? {arrow()}</a></div>
 <p class="hero-note">This is the project website. Your own DeskRally setup has its own address.</p></div>
 <div class="route-poster" aria-label="Illustration of a winding rally route"><div class="poster-top"><span>DESKRALLY / ROADBOOK</span><span aria-hidden="true">N ↑</span></div><img src="/assets/rally-route.svg" width="800" height="520" alt="A winding road through contour lines, with a route marker and checkered flag."><div class="poster-bottom"><span class="checkers" aria-hidden="true"></span><span>A straightforward way to help.</span><span aria-hidden="true">01 / DR</span></div></div>
</section>
<div class="route-strip"><div class="wrap route-strip-inner"><span><b>01</b> Windows agents</span><span><b>02</b> Browser console</span><span><b>03</b> Your infrastructure</span></div></div>
<section class="wrap section" id="overview"><div class="section-intro"><p class="eyebrow">The overview</p><h2>Two ways to connect.</h2><p>Sometimes someone is there to ask for help. Sometimes you need to reach a computer that already has an agent installed. DeskRally supports both.</p></div>
 <div class="connection-grid"><article class="connection-card"><div class="card-top"><span class="route-number">01</span><span class="small-label">Someone needs a hand</span></div><h3>One-time support</h3><p>Create a session and give the other person a code. They run the support client and approve screen sharing when they are ready.</p><a href="/docs/receiving-support/">How a support session works {arrow()}</a></article>
 <article class="connection-card dark-card"><div class="card-top"><span class="route-number">02</span><span class="small-label">A computer you manage</span></div><h3>Unattended access</h3><p>Install an agent on a computer you manage. Authorized technicians can connect again without someone entering a code each time. Access still depends on the account’s permissions.</p><a href="/docs/technician-guide/">Read the technician guide {arrow()}</a></article></div>
</section>
<section class="workbench"><div class="wrap workbench-grid"><div><p class="eyebrow">Behind the wheel</p><h2>Start with the computer<br>you need to work on.</h2><p>Choose a machine, connect, and use the tools available to your account. That might mean sharing a screen, checking system information, or working in the background. What you can do depends on your permissions and the agent.</p><a class="text-link" href="/docs/technician-guide/">Read the technician guide {arrow()}</a></div>
 <div class="console-demo" aria-label="Illustrative console, not a live connection"><div class="demo-toolbar"><span class="demo-dots" aria-hidden="true">● ● ●</span><span>DeskRally / Console</span><span class="demo-label">Illustration</span></div><div class="demo-body"><div class="demo-sidebar"><span class="eyebrow">Machines</span><div class="demo-machine active"><i aria-hidden="true"></i> Workshop PC <span>Windows</span></div><div class="demo-machine"><i aria-hidden="true"></i> Office desktop <span>Windows</span></div><div class="demo-machine"><i class="offline" aria-hidden="true"></i> Spare laptop <span>Offline</span></div></div><div class="demo-stage"><div class="route-cross" aria-hidden="true">↗</div><strong>No machine selected.</strong><span>Select a machine to begin.</span></div></div><div class="demo-footer">Illustrative view · No real machines or account data</div></div></div>
</section>
<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">The roadbook</p><h2>Start with what you need to do.</h2></div><a class="text-link" href="/docs/">All documentation {arrow()}</a></div><div class="guide-grid">{card('receiving-support','Here for help?','Know what to expect before you share your screen.','For support guests')}{card('technician-guide','Supporting a computer?','Find your way around a session and its controls.','For technicians')}{card('self-hosting','Running your own setup?','Understand the components and plan your deployment.','For self-hosters')}</div></section>
<section class="source-band"><div class="wrap source-band-inner"><div><p class="eyebrow">Follow the project</p><h2>The source is being prepared.</h2><p>The website is public, but the code repository is still private while I put the release together. I’ll add the GitHub link here when it is ready.</p></div><a class="button paper" href="/source/">Source release status {arrow()}</a></div></section>
''','home')
page('/docs/','Documentation','DeskRally documentation for support guests, technicians, and self-hosters.','''<section class="wrap page-head"><p class="eyebrow">The roadbook</p><h1>Let’s get you started.</h1><p>Choose the guide that fits what you are trying to do. Start with receiving support if someone is helping you with your computer.</p></section><section class="wrap docs-library"><label class="search-label" for="docs-search">Search the guides</label><div class="search-field"><span aria-hidden="true">⌕</span><input id="docs-search" type="search" placeholder="Try ‘session code’, ‘Windows’, or ‘hosting’" autocomplete="off" aria-controls="guide-results"></div><p class="search-count" id="search-count" role="status" aria-live="polite">Five guides, depending on what you need.</p><div class="guide-grid" id="guide-results">'''+''.join(card(slug,title,desc,label) for slug,label,title,desc in DOCS)+'''</div><p id="search-empty" hidden>No guides found. Try a broader term, such as “support” or “access”.</p><noscript><p>Search needs JavaScript. All guides are listed above and work without it.</p></noscript></section>''')
CONTENT={
'getting-started':('Start here','Here is what you need before you connect.', """<p>DeskRally is a project for remote support and unattended access to Windows computers. A technician uses the browser console to connect to a computer running an agent. Each setup has its own server address and accounts.</p><div class="note"><strong>Looking for help with your computer?</strong><p>This is the project website. It does not run a public help desk. Use the address and instructions from the technician you contacted for help.</p></div><h2 id="choose">Start with what you need to do</h2><ul><li><strong>You need help with your computer.</strong> Read <a href="/docs/receiving-support/">receiving support</a>. You do not need a technician account to join a one-time support session.</li><li><strong>You help other people with their computers.</strong> Read the <a href="/docs/technician-guide/">technician guide</a>. You will need an account on the server you are using and permission to access the computer.</li><li><strong>You want to run your own server.</strong> Start with the <a href="/docs/self-hosting/">self-hosting overview</a>. It explains the components and what you will need to maintain.</li></ul><h2 id="connection-types">Decide how you will connect</h2><h3>One-time support</h3><p>The technician creates a session and shares a code or link. The person receiving help runs the support client and approves sharing on their computer. Entering the code prepares the session; it does not approve screen sharing.</p><h3>Unattended access</h3><p>An administrator installs an agent on a computer that needs ongoing access. Technicians can then connect according to the account permissions and server policies. Someone does not need to enter a code for each connection.</p><h2 id="prepare">A few things to check first</h2><ul><li>Make sure you have the right computer and server address.</li><li>Check that the computer has an internet connection.</li><li>Close anything you do not want visible before sharing your screen.</li><li>Use the software and instructions supplied by the administrator of your setup.</li></ul><h2 id="availability">Where are the code and downloads?</h2><p>I am still preparing the public source release. There is no public installer or hosted support account available through this website yet. The <a href="/source/">source page</a> explains where that stands.</p>"""),
'receiving-support':('Receiving support','What to expect when someone helps with your computer.', """<p>Your technician will give you a support address and a session code or link. These instructions are for a one-time support session on a Windows computer.</p><div class="note caution"><strong>Make sure this is help you asked for.</strong><p>Use contact details you already trust. If someone calls unexpectedly and asks you to install remote-access software, stop and contact your usual support person.</p></div><h2 id="contact">1. Get the details from your technician</h2><p>Explain the problem and confirm which computer needs help. Ask for the support address and a session code or link. Keep the code private rather than posting it in a public issue or chat.</p><h2 id="client">2. Open the support client</h2><p>Use the download or session bundle from your technician’s server, and run it on the computer that needs help. If Windows or the browser shows a warning, stop and read the exact message to your technician. Do not assume it is safe to bypass.</p><h2 id="code">3. Enter the session code</h2><p>Enter the code, or follow the support link your technician gave you. If it is rejected or has expired, ask for another one. This gets the session ready; it does not give permission to share your screen.</p><h2 id="consent">4. Approve sharing when you are ready</h2><p>Check the support address shown in the permission prompt. Close any sensitive windows, then approve sharing and control when you are ready. The client shows a support indicator while the session is running.</p><h2 id="finish">5. End the session</h2><p>You can end the session from the support client. Let your technician know when you are finished, and close the client. A one-time support client and a permanently installed agent are different. If you are not sure which one you have, ask before continuing.</p><h2 id="troubleshooting">If something is not working</h2><ul><li><strong>The code does not work:</strong> ask the technician to check it and confirm the session is still available.</li><li><strong>The download is blocked:</strong> tell your technician what the warning says. Do not turn off protection to get past it.</li><li><strong>The connection does not start:</strong> check your internet connection and confirm the server address.</li><li><strong>Something is unexpected:</strong> end the session and contact your technician through a known channel.</li></ul>"""),
'technician-guide':('Technician guide','Connect to the computer, then work through the problem.', """<p>The browser console is where you find machines and start support sessions. The controls you see depend on your account permissions, the server policies, and what the agent supports.</p><h2 id="sign-in">Sign in to the right server</h2><p>Use the console address your administrator supplied. Check the organization field, then sign in using the method configured for your account. If verification codes are enabled, enter the code as part of signing in.</p><h2 id="pick-route">Choose how to connect</h2><ul><li><strong>A computer with an agent already installed:</strong> select a machine your account can access and start a connection.</li><li><strong>Someone asking for one-time help:</strong> create an attended session and share the code or support link directly with that person.</li></ul><p>Session codes, support bundles, account details, and enrollment tokens should stay out of public issues.</p><h2 id="tools">Use the tools that fit the problem</h2><p>The session toolbar gives you screen and input controls. Depending on your permissions and the agent, you may also have file access, system information, and background administration tools.</p><p>Explain significant changes to the person you are helping. A background command or file operation can affect their computer just as much as something you do with the mouse.</p><h2 id="reconnect">If the connection is interrupted</h2><p>Check the connection status before trying the action again. A computer or client that has restarted may need time to become available. First check whether the original session is still active, so you do not create duplicate sessions while troubleshooting.</p><h2 id="close">Before you finish</h2><ol><li>Explain what changed and check whether the problem is resolved.</li><li>Stop any commands or transfers that should not continue.</li><li>Disconnect and confirm the session has ended.</li><li>Sign out when you are finished on a shared computer.</li></ol><h2 id="permissions">If a control is missing or disabled</h2><p>It may be an account restriction, a server policy, a disconnected agent, or a platform limitation. Check with the administrator. Sharing another person’s credentials is not a way to fix an access problem.</p>"""),
'self-hosting':('Self-hosting','Here is what you will be running.', """<p>DeskRally has a browser console, server services, and Windows agents. Running your own setup means maintaining those components and the infrastructure that connects them.</p><div class="note"><strong>The public source release is still being prepared.</strong><p>This guide covers the architecture and planning. I will add versioned build and installation instructions with the source release.</p></div><h2 id="architecture">How the components fit together</h2><div class="architecture" aria-label="Connection architecture"><div>Browser console<span>The technician’s interface</span></div><b aria-hidden="true">↕</b><div>Control plane & signaling<span>Accounts, permissions, and session setup</span></div><b aria-hidden="true">↕</b><div>Windows agent<span>Screen sharing and remote tools</span></div><p>WebRTC carries session media. Relay infrastructure helps when the computers cannot make a direct connection.</p></div><dl><dt>Web console</dt><dd>The browser interface uses React and TypeScript.</dd><dt>Control plane and connection services</dt><dd>Go services handle the API, signaling, and relay work.</dd><dt>Windows agent</dt><dd>Rust components handle the remote computer side of the session.</dd><dt>Database</dt><dd>PostgreSQL stores the application records. It should stay private to your setup.</dd><dt>STUN/TURN</dt><dd>These services help computers connect across different networks. Include relay capacity in your planning rather than assuming every connection will be direct.</dd></dl><h2 id="plan">What to plan for</h2><ul><li>A server environment for the application services and database.</li><li>A domain and HTTPS certificates for browser access.</li><li>A reachable STUN/TURN setup and the necessary network rules.</li><li>Windows computers for the agents, with permission to install the software.</li><li>Backups, monitoring, updates, and a way to recover administrative access.</li></ul><h2 id="boundaries">Keep public and private services separate</h2><p>The public project website and your authenticated console do different jobs. Database ports and internal service listeners should not be exposed as public websites. Use credentials specific to your setup, and keep private signing material out of source control.</p><h2 id="responsibility">What you will need to maintain</h2><p>You will be responsible for accounts, access policies, agents, network configuration, backups, and updates. Start with a small test setup and check both connectivity and permissions before relying on it for other people’s computers.</p>"""),
'security':('Security & consent','Be clear about who can connect and what they can do.', """<p>Remote access lets someone see information and make changes to a computer. That is why it should be clear who is connecting, what access they have, and how the session ends.</p><h2 id="guests">If you are receiving help</h2><ul><li>Start with a technician you meant to contact.</li><li>Check the support address and read the permission prompts.</li><li>Close sensitive windows before sharing your screen.</li><li>End the session if something is unexpected.</li></ul><h2 id="operators">If you run or support a setup</h2><ul><li>Give each person their own account and the access they need for their work.</li><li>Use HTTPS and protect administrator credentials and verification factors.</li><li>Keep track of computers that have a permanent agent installed.</li><li>Maintain the agents, server, operating systems, and database.</li><li>Protect logs and audit records, which can contain sensitive information.</li></ul><h2 id="public-information">Keep sensitive information out of public issues</h2><p>Passwords, enrollment tokens, private signing keys, session codes, account records, personal screenshots, and raw logs should not go in a public repository or issue. Use a generic example when explaining a problem.</p><h2 id="issues">If you find a security concern</h2><p>Private reporting instructions will be published with the source repository. Until then, do not publish details that expose a real setup or someone’s credentials. For a problem on a server you use, contact its administrator through your usual private channel.</p><h2 id="scope">What this guidance means</h2><p>These are operating practices, not a security certification. The security of a particular setup also depends on its version, configuration, infrastructure, and administration.</p>""")}
for slug,(title,subtitle,body) in CONTENT.items():
 page('/docs/'+slug+'/',title,next(d[3] for d in DOCS if d[0]==slug),f'<p class="eyebrow">The roadbook / {title}</p><h1>{title}</h1><p class="article-lede">{subtitle}</p>'+body,'doc')
page('/about/','About DeskRally','What DeskRally does, why it uses a road rally theme, and where the project stands.',"""<section class="wrap page-head"><p class="eyebrow">About the project</p><h1>Helping with a computer<br>should make sense.</h1><p>I’m building DeskRally to make remote support easier to follow. It should be clear how to connect, what access you are giving someone, and how to end the session.</p></section><section class="wrap about-grid section"><div><h2>Why the road rally theme?</h2><p>I’m using the road rally theme to give the project some personality. Working through a computer problem often means figuring out where you are, checking what is in the way, and deciding what to try next.</p><p>The controls still need to use familiar words. Sign in should mean sign in. Someone asking for help should not have to learn the theme before they can use the software.</p></div><div class="about-sign"><span class="eyebrow">The idea</span><h2>A practical way<br>to help with<br>a computer.</h2><span class="checkers" aria-hidden="true"></span></div></section><section class="wrap narrow section"><h2>What DeskRally does</h2><p>DeskRally supports one-time remote support and unattended access to managed computers. It is Windows-first, with a browser console and services you host yourself. The project uses Rust, Go, and TypeScript.</p><h2>What this website is for</h2><p>This is where I explain the project and how the main workflows fit together. It does not provide a public help desk, create technician accounts, or collect session codes. If someone is helping you, use the address they gave you.</p><h2>Where things stand</h2><p>I’m preparing the public source release. The website is available now, and I’ll add the GitHub link when the repository is ready. In the meantime, the <a href="/docs/">documentation</a> explains the support process and the parts of a self-hosted setup.</p></section>""")
page('/source/','Source release','The current status of the DeskRally public source release and its Apache 2.0 license.',"""<section class="wrap page-head"><p class="eyebrow">Project source</p><h1>I’m getting the source<br>ready to share.</h1><p>The website is public. The code repository is still private while I put the initial release together and review what belongs in it.</p></section><section class="wrap narrow section"><div class="release-status"><span class="status-dot" aria-hidden="true"></span><div><strong>The public source is not available yet.</strong><p>I’ll put the GitHub link here when it is ready.</p></div></div><h2>The license</h2><p>I’ve chosen Apache License 2.0 for original DeskRally project work. It allows use and modification under its terms, including commercial use. Third-party components keep their own licenses.</p><p>You can read the <a href="/LICENSE">license</a> and <a href="/NOTICE">project notice</a>. The license includes warranty and liability provisions. It does not guarantee immunity from liability or certify the software’s security.</p><h2>What is still being prepared</h2><p>The source release will need working setup instructions, the required license notices, and guidance for contributions and private security reports. I do not have a release date to promise yet.</p><h2>What you can read now</h2><p>The guides explain one-time support, the technician workflow, and the components you would run yourself.</p><div class="actions"><a class="button primary" href="/docs/">Read the guides →</a><a class="text-link" href="/about/">About DeskRally ↗</a></div></section>""")
page('/privacy/','Website privacy','What this project website does, what it asks for, and how it differs from a DeskRally deployment.',"""<section class="wrap page-head"><p class="eyebrow">Website information</p><h1>Here is what<br>this website does.</h1><p>This page covers the project website. A DeskRally server you use for support is a separate setup.</p></section><section class="wrap narrow section"><h2>The website itself</h2><p>It serves static pages, styles, scripts, and illustrations. The documentation search runs in your browser, so the words you type are not sent to a search service.</p><h2>What I have not added</h2><p>This version has no analytics, advertising, contact forms, account registration, embedded videos, third-party fonts, or application cookies. It does not ask for session codes or technician credentials.</p><h2>Hosting</h2><p>Cloudflare hosts the public website. The hosting provider may process ordinary request information, such as an IP address and browser details, to deliver and protect the site.</p><h2>Your support session</h2><p>Accounts, support sessions, audit records, and remote-computer data belong to the server you use. Ask that server’s administrator how the information is handled.</p></section>""")

NAV=[('/docs/','Documentation'),('/about/','About'),('/source/','GitHub')]
def layout(path,entry):
 nav=''.join(f'<a href="{href}"'+(' aria-current="page"' if path==href or href=='/docs/' and path.startswith('/docs/') else '')+f'>{name}</a>' for href,name in NAV)
 body=entry['body']
 if entry['kind']=='doc':
  side=''.join(f'<a href="/docs/{slug}/"'+(' aria-current="page"' if path==f'/docs/{slug}/' else '')+f'>{label}</a>' for slug,label,title,desc in DOCS)
  headings=re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',body)
  toc=''.join(f'<a href="#{anchor}">{title}</a>' for anchor,title in headings)
  body=f'<div class="wrap doc-layout"><aside class="doc-nav"><a class="doc-nav-home" href="/docs/">← All documentation</a><p class="eyebrow">Guides</p>{side}</aside><article class="article">{body}<div class="article-next"><a href="/docs/">← Back to the roadbook</a><a href="/docs/security/">Security & consent ↗</a></div></article><aside class="on-this-page"><p class="eyebrow">On this page</p>{toc}</aside></div>'
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(entry['description'],quote=True)}"><meta name="theme-color" content="#13283e"><meta name="robots" content="index,follow"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'self'; script-src 'self'; img-src 'self'; connect-src 'none'; base-uri 'none'; form-action 'none'; frame-src 'none'"><meta property="og:title" content="{html.escape(entry['title'],quote=True)} · DeskRally"><meta property="og:description" content="{html.escape(entry['description'],quote=True)}"><meta property="og:type" content="website"><title>{entry['title']} · DeskRally</title><link rel="icon" type="image/svg+xml" href="/assets/rally-mark.svg"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/site.js" defer></script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="wrap nav-inner"><a class="wordmark" href="/" aria-label="DeskRally home"><img src="/assets/rally-mark.svg" alt="" width="34" height="34">DeskRally</a><nav aria-label="Main navigation">{nav}</nav><a class="nav-start" href="/docs/getting-started/">Start here <span aria-hidden="true">↗</span></a></div></header><main id="main">{body}</main><footer class="site-footer"><div class="wrap footer-inner"><div><a class="wordmark" href="/"><img src="/assets/rally-mark.svg" alt="" width="28" height="28">DeskRally</a><p>Remote support. Keep it simple.</p></div><nav aria-label="Footer navigation"><a href="/docs/">Documentation</a><a href="/about/">About</a><a href="/source/">Source release</a><a href="/privacy/">Website privacy</a></nav><span class="footer-stamp" aria-hidden="true">DR / KEEP MOVING<br><span class="checkers"></span></span></div></footer></body></html>'''
OUT.mkdir(exist_ok=True)
(OUT/'assets').mkdir(parents=True,exist_ok=True)
for path,entry in PAGES.items():
 dest=OUT/path.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(layout(path,entry),encoding='utf8',newline='\n')
not_found={'title':'Page not found','description':'This route could not be found on the DeskRally project website.','kind':'standard','body':'<section class="wrap page-head"><p class="eyebrow">Route not found / 404</p><h1>That page could not be found.</h1><p>The address may be wrong, or the page may have moved. Try the documentation or go back to the home page.</p></section><section class="wrap section"><div class="actions"><a class="button primary" href="/">Back to DeskRally →</a><a class="text-link" href="/docs/">Open the documentation ↗</a></div></section>'}
(OUT/'404.html').write_text(layout('/404/',not_found).replace('content="index,follow"','content="noindex,follow"'),encoding='utf8',newline='\n')
shutil.copy2(ROOT/'_headers',OUT/'_headers')
for legal_file in ['LICENSE','NOTICE']:
 shutil.copy2(ROOT.parent/legal_file,OUT/legal_file)
for p in (ROOT/'assets').iterdir():
 if p.is_file():shutil.copy2(p,OUT/'assets'/p.name)
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://deskrally.com/sitemap.xml\n',encoding='utf8')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://deskrally.com'+path+'</loc></url>' for path in PAGES)+'</urlset>',encoding='utf8')
index=[{'path':path,'title':entry['title'],'text':html.unescape(re.sub('<[^>]+>',' ',entry['body']))} for path,entry in PAGES.items() if path.startswith('/docs/') and path!='/docs/']
js='''"use strict";
const guides=GUIDE_DATA;
const input=document.querySelector("#docs-search");
if(input){const cards=[...document.querySelectorAll("#guide-results .doc-card")];const count=document.querySelector("#search-count");const empty=document.querySelector("#search-empty");input.addEventListener("input",()=>{const words=input.value.toLocaleLowerCase().trim().split(/\\s+/).filter(Boolean);let visible=0;for(const card of cards){const item=guides.find(g=>g.path===card.getAttribute("href"));const match=words.every(w=>(item.title+" "+item.text).toLocaleLowerCase().includes(w));card.hidden=!match;if(match)visible++;}count.textContent=visible+" guide"+(visible===1?"":"s")+" found.";empty.hidden=visible!==0;});}
'''.replace('GUIDE_DATA',json.dumps(index,ensure_ascii=False))
(OUT/'assets/site.js').write_text(js,encoding='utf8',newline='\n')
print(json.dumps({'pages':len(PAGES)+1,'docs':len(index),'output':'dist','external_runtime_dependencies':0}))
